  "Arrossega per girar el cel, fes pinça o roda per ampliar i usa els botons cardinals per orientar-te. «Posta de sol» i «Nit astronòmica» calculen l’hora per a la localitat i data escollides. Totes les hores es mostren en hora peninsular Europe/Madrid, amb el canvi CET/CEST aplicat automàticament.": {
    "es": "Arrastra para girar el cielo, haz pinza o rueda para ampliar y usa los botones cardinales para orientarte. «Puesta de sol» y «Noche astronómica» calculan la hora para la localidad y fecha seleccionadas. Todas las horas se muestran en hora peninsular Europe/Madrid, con el cambio CET/CEST aplicado automáticamente.",
    "en": "Drag to rotate the sky, pinch or zoom to enlarge and use the cardinal buttons to orient yourself. «Sunset» and «Astronomical Night» calculate the time for the selected location and date. All times are shown in Europe/Madrid daylight saving time, with CET/CEST automatically applied.",
    "fr": "Glissez pour faire tourner le ciel, faites un zoom ou faites glisser pour agrandir et utilisez les boutons cardinaux pour vous orienter. «Coucher de soleil» et «Nuit astronomique» calculent l'heure pour la localisation et la date sélectionnées. Toutes les heures sont affichées en heure d'été de l'Europe/Madrid, avec le changement CET/CEST appliqué automatiquement."
  },
