  "Bellaterra com a referència principal i Girona com a complement de vegetació més humida.": {
    "es": "Bellaterra como referencia principal y Girona como complemento de vegetación más húmeda.",
    "en": "Bellaterra as the main reference and Girona as a complement of more humid vegetation.",
    "fr": "Bellaterra comme référence principale et Girona comme complément de végétation plus humide."
  },
  "Bellaterra és la referència principal recomanada per a Sant Celoni. Girona aporta un contrast complementari de vegetació més humida; si no està disponible, es mostra Manresa com a alternativa identificada. Els nivells mai no es promitgen i no són una mesura local.": {
    "es": "Bellaterra es la referencia principal recomendada para Sant Celoni. Girona aporta un contraste complementario de vegetación más húmeda; si no está disponible, se muestra Manresa como alternativa identificada. Los niveles nunca se promedian y no son una medida local.",
    "en": "Bellaterra is the recommended main reference for Sant Celoni. Girona provides a complementary contrast of more humid vegetation; if unavailable, Manresa is shown as the identified alternative. Levels are never promised and are not a local measure.",
    "fr": "Bellaterra est la référence principale recommandée pour Sant Celoni. Girona apporte un contraste complémentaire de végétation plus humide ; si elle n'est pas disponible, Manresa est affichée comme alternative identifiée. Les niveaux ne sont jamais promis et ne constituent pas une mesure locale."
  },
