    "es": "Busca temperatura y punto de rocío muy próximos, viento suave y una reducción visible del paisaje a la webcam. La visibilidad puede variar mucho según la dirección y entre el fondo de la vall y los taludes.",
    "en": "Search for very close temperature and dew point, light wind and a visible reduction of the landscape on the webcam. Visibility may vary greatly depending on the direction and between the valley floor and the slopes.",
    "fr": "Recherchez des températures et point de rosée très proches, vent léger et une réduction visible du paysage sur la webcam. La visibilité peut varier beaucoup selon la direction et entre le fond de la vallée et les pentes."
