  "Cal mirar fenomen, territori, nivell i vigència. Un avís expressa risc potencial, no garanteix que el fenomen afecti cada carrer. Sempre prevalen el detall oficial i les indicacions de Protecció Civil.": {
    "es": "Debe revisar fenómeno, territorio, nivel y vigencia. Un aviso expresa riesgo potencial, no garantiza que el fenómeno afecte cada calle. Siempre prevalecen el detalle oficial y las indicaciones de Protección Civil.",
    "en": "You must check phenomenon, territory, level and validity. A warning expresses potential risk, it does not guarantee that the phenomenon affects each street. Always prevail the official details and the instructions from Civil Protection.",
    "fr": "Il faut vérifier le phénomène, le territoire, le niveau et la validité. Un avertissement exprime un risque potentiel, il ne garantit pas que le phénomène affecte chaque rue. Les détails officiels et les instructions de la Protection Civile prévalent toujours."
  },
