  "Cap model substitueix els avisos oficials ni garanteix el temps exacte en un carrer concret.": {
    "es": "Ningún modelo sustituye las alertas oficiales ni garantiza el tiempo exacto en una calle concreta.",
    "en": "No model replaces official warnings or guarantees the exact weather on a specific street.",
    "fr": "Aucun modèle ne remplace les alertes officielles ni ne garantit le temps exact sur une rue spécifique."
  },
  "Cap model és sempre el millor a tot arreu. Comença per la font oficial del país i utilitza els models i comparadors per entendre la incertesa.": {
    "es": "Ningún modelo es siempre el mejor en todas partes. Comienza por la fuente oficial del país y utiliza los modelos y comparadores para entender la incertidumbre.",
    "en": "No model is always the best everywhere. Start with the country's official source and use models and comparators to understand uncertainty.",
    "fr": "Aucun modèle n'est toujours le meilleur partout. Commencez par la source officielle du pays et utilisez les modèles et les comparateurs pour comprendre l'incertitude."
  },
  "Cap percentatge de «precisió» inventat. Calen almenys 30 dies d’entrenament elegibles i 14 de prova per començar a interpretar els resultats; això no garanteix qualitat ni superioritat.": {
    "es": "Ningún porcentaje de «precisión» inventado. Se necesitan al menos 30 días de entrenamiento elegibles y 14 de prueba para comenzar a interpretar los resultados; esto no garantiza calidad ni superioridad.",
    "en": "No invented «precision» percentage. At least 30 days of eligible training and 14 days of testing are needed to start interpreting results; this does not guarantee quality or superiority.",
    "fr": "Aucun pourcentage de «précision» inventé. Il faut au moins 30 jours de formation éligible et 14 jours de test pour commencer à interpréter les résultats ; cela ne garantit pas la qualité ni la supériorité."
  },
