  "Cinc productes oficials de Météo-France per observar el curt termini, la previsió immediata i la incertesa. Aquesta és una capa experimental: complementa la previsió operativa, no la substitueix.": {
    "es": "Cinco productos oficiales de Météo-France para observar el corto plazo, la previsión inmediata y la incertidumbre. Esta es una capa experimental: complementa la previsión operativa, no la sustituye.",
    "en": "Five official products from Météo-France to observe the short term, immediate forecast and uncertainty. This is an experimental layer: complements the operational forecast, it does not replace it.",
    "fr": "Cinq produits officiels de Météo-France pour observer le court terme, la prévision immédiate et l'incertitude. Il s'agit d'une couche expérimentale : elle complète la prévision opérationnelle, elle ne la remplace pas."
  },
