  "Cobertura mundial combinada amb el catàleg local i regional de la Xarxa Sísmica de Catalunya. Els marcadors ICGC tenen contorn blau. Les localitzacions i magnituds poden ser revisades; no és un sistema d’avisos.": {
    "es": "Cobertura mundial combinada con el catálogo local y regional de la Red Sísmica de Catalunya. Los marcadores ICGC tienen contorno azul. Las localizaciones y magnitudes pueden ser revisadas; no es un sistema de alertas.",
    "en": "Global coverage combined with the local and regional catalog of the Catalonia Seismic Network. ICGC markers have a blue outline. Locations and magnitudes can be reviewed; it is not an alert system.",
    "fr": "Couverture mondiale combinée avec le catalogue local et régional de la Réseau Sismique de Catalogne. Les marqueurs ICGC ont un contour bleu. Les localisations et magnitudes peuvent être révisées ; ce n'est pas un système d'alerte."
  },
