  "Es processen el nom, el correu, el motiu i el missatge exclusivament per respondre. El control antiabús conserva temporalment identificadors irreversibles derivats de la IP i del correu, no els valors en text clar.": {
    "es": "Se procesan el nombre, el correo, el motivo y el mensaje exclusivamente para responder. El control antiabuso conserva temporalmente identificadores irreversibles derivados de la IP y del correo, no los valores en texto claro.",
    "en": "The name, email, reason, and message are processed exclusively to respond. The abuse prevention system temporarily stores irreversible identifiers derived from the IP and email, not plain text values.",
    "fr": "Le nom, l'adresse e-mail, la raison et le message sont traités exclusivement pour répondre. Le système de prévention des abus conserve temporairement des identifiants irréversibles dérivés de l'IP et de l'e-mail, pas les valeurs en texte brut."
  },
