  "Escala oficial XAC: 0 nul · 1 baix · 2 mig · 3 alt · 4 màxim. La tendència indica augment, estabilitat o descens durant el període. Informació orientativa, no diagnòstica; la sensibilitat individual varia. Font:": {
    "es": "Escala oficial XAC: 0 nulo · 1 bajo · 2 medio · 3 alto · 4 máximo. La tendencia indica aumento, estabilidad o descenso durante el período. Información orientativa, no diagnóstica; la sensibilidad individual varía. Fuente:",
    "en": "Official XAC scale: 0 null · 1 low · 2 medium · 3 high · 4 maximum. The trend indicates increase, stability or decrease during the period. Information is advisory, not diagnostic; individual sensitivity varies. Source:",
    "fr": "Échelle officielle XAC : 0 nul · 1 faible · 2 moyen · 3 élevé · 4 maximal. La tendance indique une augmentation, une stabilité ou une diminution pendant la période. L'information est indicative, non diagnostique ; la sensibilité individuelle varie. Source :"
  },
