  "Fonta": {
    "es": "Fuenta",
    "en": "Source",
    "fr": "Source"
  },
  "Fonta contra les alternatives": {
    "es": "Fuente contra las alternativas",
    "en": "Source against alternatives",
    "fr": "Source contre les alternatives"
  },
  "Fonta contrasta prediccions desades abans de l’episodi amb les observacions reals de l’estació. Només proposa pesos locals quan cada model acumula prou casos comparables; AROME HD continua com a candidat experimental.": {
    "es": "Fuente contrasta predicciones deseadas antes del episodio con las observaciones reales de la estación. Solo propone pesos locales cuando cada modelo acumula suficientes casos comparables; AROME HD continúa como candidato experimental.",
    "en": "Source contrasts desired predictions before the episode with the station's real observations. It only proposes local weights when each model accumulates enough comparable cases; AROME HD continues as an experimental candidate.",
    "fr": "Source contraste les prévisions souhaitées avant l'épisode avec les observations réelles de la station. Elle ne propose des poids locaux que lorsque chaque modèle accumule suffisamment de cas comparables ; AROME HD reste un candidat expérimental."
  },
  "Fonta encara no és una previsió validada. Compara models i aprèn a corregir errors locals en un entorn de prova. No substitueix la previsió habitual ni els avisos de Meteocat, AEMET o Protecció Civil.": {
    "es": "Fonta aún no es una previsión validada. Compara modelos y aprende a corregir errores locales en un entorno de prueba. No sustituye la previsión habitual ni los avisos de Meteocat, AEMET o Protección Civil.",
    "en": "Fonta is not yet a validated forecast. Compare models and learn to correct local errors in a test environment. It does not replace the standard forecast nor the warnings from Meteocat, AEMET, or Civil Protection.",
    "fr": "Fonta n'est pas encore une prévision validée. Comparez les modèles et apprenez à corriger les erreurs locales dans un environnement de test. Elle ne remplace pas la prévision habituelle ni les alertes de Meteocat, AEMET ou la Protection civile."
  },
  "Fonta · Previsió local en evolució": {
    "es": "Fonta · Previsión local en evolución",
    "en": "Fonta · Local forecast in evolution",
    "fr": "Fonta · Prévision locale en évolution"
  },
  "Fonta · laboratori": {
    "es": "Fuente · laboratorio",
    "en": "Source · laboratory",
    "fr": "Source · laboratoire"
  },
  "Fonta és una combinació meteorològica local, no un model físic nou ni una intel·ligència artificial que aprengui sense control. El Worker desa, abans que passi cada dia, les prediccions de Best Match, ECMWF, ICON, GFS i AROME per als mateixos horitzons.": {
    "es": "Fonta es una combinación meteorológica local, no un modelo físico nuevo ni una inteligencia artificial que aprenda sin control. El Worker guarda, antes de pasar cada día, las predicciones de Best Match, ECMWF, ICON, GFS y AROME para los mismos horizontes.",
    "en": "Fonta is a local meteorological combination, not a new physical model or an uncontrolled learning artificial intelligence. The Worker saves, before each day passes, the forecasts from Best Match, ECMWF, ICON, GFS and AROME for the same horizons.",
    "fr": "Fonta est une combinaison météorologique locale, pas un nouveau modèle physique ni une intelligence artificielle apprenant sans contrôle. Le Worker sauvegarde, avant que chaque jour ne passe, les prévisions de Best Match, ECMWF, ICON, GFS et AROME pour les mêmes horizons."
  },
  "Fontanillas": {
    "es": "Fontanillas",
    "en": "Fontanillas",
    "fr": "Fontanillas"
  },
  "Fontanillas encara no té altres anys comparables. Mentrestant, aquí tens efemèrides històriques verificades properes a aquesta data.": {
    "es": "Fontanillas aún no tiene otros años comparables. Mientras tanto, aquí tienes efemérides históricas verificadas próximas a esta fecha.",
    "en": "Fontanillas still has no comparable other years. Meanwhile, here are verified historical ephemera close to this date.",
    "fr": "Fontanillas n'a toujours pas d'autres années comparables. Pour l'instant, voici des éphémérides historiques vérifiées proches de cette date."
  },
  "Fontanillas i fins a cinc estacions properes, descobertes automàticament i normalitzades amb les mateixes unitats.": {
    "es": "Fontanillas y hasta cinco estaciones próximas, descubiertas automáticamente y normalizadas con las mismas unidades.",
    "en": "Fontanillas and up to five nearby stations, automatically discovered and normalized with the same units.",
    "fr": "Fontanillas et jusqu'à cinq stations proches, découvertes automatiquement et normalisées avec les mêmes unités."
  },
  "Fontanillas mesura un punt concret de Sant Celoni. L’altura, l’entorn immediat, l’ombra, el vent i l’hora exacta poden fer-la diferent d’una estació oficial pròxima. No corregim intuïtivament les lectures per fer-les coincidir.": {
    "es": "Fontanillas mide un punto concreto de Sant Celoni. La altura, el entorno inmediato, la sombra, el viento y la hora exacta pueden hacerla diferente de una estación oficial próxima. No corregimos intuitivamente las lecturas para hacerlas coincidir.",
    "en": "Fontanillas measures a specific point of Sant Celoni. The altitude, the immediate surroundings, the shadow, the wind and the exact time can make it different from an official nearby station. We do not intuitively correct readings to make them match.",
    "fr": "Fontanillas mesure un point précis de Sant Celoni. L'altitude, l'environnement immédiat, l'ombre, le vent et l'heure exacte peuvent la rendre différente d'une station officielle proche. Nous ne corrigeons pas intuitivement les lectures pour les faire correspondre."
  },
  "Fonts consultades: NOAA (lectura diària provisional), IGCC/Copernicus (indicador global multiserie de 2025), Copernicus C3S (ERA5) i Meteocat (butlletí anual de 2025). Contingut revisat el 25 d’octubre de 2026.": {
    "es": "Fuentes consultadas: NOAA (lectura diaria provisional), IGCC/Copernicus (indicador global multiserie de 2025), Copernicus C3S (ERA5) y Meteocat (boletín anual de 2025). Contenido revisado el 25 de octubre de 2026.",
    "en": "Sources consulted: NOAA (provisional daily reading), IGCC/Copernicus (multi-series global indicator of 2025), Copernicus C3S (ERA5) and Meteocat (annual bulletin of 2025). Content reviewed on October 25, 2026.",
    "fr": "Sources consultées : NOAA (lecture quotidienne provisoire), IGCC/Copernicus (indicateur global multiserie de 2025), Copernicus C3S (ERA5) et Meteocat (bulletin annuel de 2025). Contenu révisé le 25 octobre 2026."
  },
