  "Has detectat una dada estranya, vols proposar una font o tens una consulta sobre l’observatori? Envia un missatge directament des d’aquí.": {
    "es": "¿Ha detectado un dato extraño? ¿Desea proponer una fuente o tiene una consulta sobre el observatorio? Envíe un mensaje directamente desde aquí.",
    "en": "Have you detected an odd data point? Would you like to suggest a source or have a query about the observatory? Send a message directly from here.",
    "fr": "Avez-vous détecté une donnée étrange ? Souhaitez-vous proposer une source ou avez-vous une question sur l'observatoire ? Envoyez un message directement depuis ici."
  },
  "Hi ha relació directa entre la ratxa més forta i l’interval de més pluja? Respon només amb allò que permeten afirmar aquestes dades.": {
    "es": "¿Existece una relación directa entre la ráfaga más fuerte y el intervalo de mayor precipitación? Responda únicamente con lo que permiten afirmar estos datos.",
    "en": "Is there a direct relationship between the strongest gust and the period of heaviest rain? Answer only with what these data allow to assert.",
    "fr": "Y a-t-il une relation directe entre la rafale la plus forte et l'intervalle de pluies les plus intenses ? Répondez uniquement avec ce que ces données permettent d'affirmer."
  },
  "Hidrata’t, evita les hores de més calor i vigila infants, gent gran i persones vulnerables.": {
    "es": "Hidrátate, evita las horas de mayor calor y vigila a los niños, a las personas mayores y a las personas vulnerables.",
    "en": "Hydrate yourself, avoid the hours of highest heat and watch out for children, the elderly and vulnerable people.",
    "fr": "Hydratez-vous, évitez les heures de plus forte chaleur et surveillez les enfants, les personnes âgées et les personnes vulnérables."
  },
