  "Les actualitzacions del mateix episodi s’agrupen al llistat": {
    "es": "Las actualizaciones del mismo episodio se agrupan en la lista.",
    "en": "Updates of the same episode are grouped in the list.",
    "fr": "Les mises à jour du même épisode sont regroupées dans la liste."
  },
  "Les captures de l’API de previsió conserven què estava disponible en consultar-la. No coneixem l’hora exacta d’inicialització de cada sortida: es registra com a desconeguda, mai com l’hora de captura. Els extrems de l’estació es mostregen aproximadament cada cinc minuts i poden diferir dels extrems reals.": {
    "es": "Las capturas de la API de previsión conservan qué estaba disponible al consultarla. No conocemos la hora exacta de inicialización de cada salida: se registra como desconocida, nunca como la hora de captura. Los extremos de la estación se muestran aproximadamente cada cinco minutos y pueden diferir de los extremos reales.",
    "en": "API forecast snapshots preserve what was available when queried. We do not know the exact initialization time of each output: it is recorded as unknown, never as the capture time. Station extremes are displayed approximately every five minutes and may differ from real extremes.",
    "fr": "Les captures d'écran de la prévision API conservent ce qui était disponible lors de la consultation. Nous ne connaissons pas l'heure exacte d'initialisation de chaque sortie : elle est enregistrée comme inconnue, jamais comme l'heure de capture. Les extrêmes de la station sont affichés environ tous les cinq minutes et peuvent différer des extrêmes réels."
  },
  "Les corbes combinen l’arxiu propi persistent de l’estació amb Weather Underground com a suport de l’històric recent. La resolució s’adapta automàticament al període seleccionat.": {
    "es": "Las curvas combinan el archivo propio persistente de la estación con Weather Underground como soporte del histórico reciente. La resolución se adapta automáticamente al período seleccionado.",
    "en": "Curves combine the station's own persistent archive with Weather Underground as support for recent history. Resolution automatically adapts to the selected period.",
    "fr": "Les courbes combinent l'archive propre persistante de la station avec Weather Underground en tant que support de l'historique récent. La résolution s'adapte automatiquement à la période sélectionnée."
  },
  "Les dades només s’utilitzen per respondre el missatge.": {
    "es": "Las datos solo se utilizan para responder el mensaje.",
    "en": "Data is only used to respond to the message.",
    "fr": "Les données ne sont utilisées que pour répondre au message."
  },
  "Les dades pròpies s’identifiquen com a lectures de l’Observatori Fontanillas. Les prediccions, mapes i altres recursos conserven l’atribució del proveïdor corresponent. No es poden presentar continguts modificats com si fossin dades oficials o originals de l’Observatori.": {
    "es": "Los datos propios se identifican como lecturas del Observatorio Fontanillas. Las predicciones, los mapas y otros recursos conservan la atribución del proveedor correspondiente. No se pueden presentar contenidos modificados como si fueran datos oficiales u originales del Observatorio.",
    "en": "Own data is identified as readings from the Fontanillas Observatory. Forecasts, maps and other resources retain the corresponding provider attribution. Modified content cannot be presented as if it were official or original data from the Observatory.",
    "fr": "Les données propres sont identifiées comme des lectures de l'Observatoire Fontanillas. Les prévisions, cartes et autres ressources conservent l'attribution du fournisseur correspondante. Des contenus modifiés ne peuvent pas être présentés comme s'ils étaient des données officielles ou originales de l'Observatoire."
  },
  "Les dades són definitives?": {
    "es": "Las datos son definitivas?",
    "en": "Are the data definitive?",
    "fr": "Les données sont-elles définitives ?"
  },
  "Les estacions, situades al mapa": {
    "es": "Las estaciones, situadas en el mapa",
    "en": "Stations, located on the map",
    "fr": "Les stations, situées sur la carte"
  },
  "Les estadístiques s’activaran quan l’arxiu disposi de cobertura.": {
    "es": "Las estadísticas se activarán cuando el archivo disponga de cobertura.",
    "en": "Statistics will activate when the file has coverage.",
    "fr": "Les statistiques s'activeront lorsque le fichier disposera d'une couverture."
  },
  "Les lectures de l’estació, la predicció i els avisos descriuen el temps i no identifiquen persones. No s’utilitzen per crear perfils personals.": {
    "es": "Las lecturas de la estación, la predicción y los avisos describen el tiempo y no identifican personas. No se utilizan para crear perfiles personales.",
    "en": "Station readings, forecasts and warnings describe the weather and do not identify people. They are not used to create personal profiles.",
    "fr": "Les relevés de la station, les prévisions et les alertes décrivent la météo et n’identifient personne. Ils ne sont pas utilisés pour établir des profils personnels."
  },
  "Les lectures, previsions i publicacions automàtiques poden contenir retards, valors incomplets o errors causats per sensors, comunicacions o serveis externs. No es garanteix un funcionament ininterromput ni l’exactitud absoluta de totes les dades.": {
    "es": "Las lecturas, predicciones y publicaciones automáticas pueden contener retrasos, valores incompletos o errores causados por sensores, comunicaciones o servicios externos. No se garantiza un funcionamiento ininterrumpido ni la exactitud absoluta de todos los datos.",
    "en": "Readings, forecasts and automatic publications may contain delays, incomplete values or errors caused by sensors, communications or external services. Continuous operation and absolute accuracy of all data are not guaranteed.",
    "fr": "Les lectures, prévisions et publications automatiques peuvent contenir des retards, des valeurs incomplètes ou des erreurs causées par les capteurs, les communications ou les services externes. Un fonctionnement ininterrompu et une exactitude absolue de toutes les données ne sont pas garantis."
  },
  "Les previsions apareixeran amb data i hora de captura quan hi hagi un arxiu vigent.": {
    "es": "Las predicciones aparecerán con fecha y hora de captura cuando exista un archivo vigente.",
    "en": "Forecasts will appear with capture date and time when a valid file exists.",
    "fr": "Les prévisions apparaîtront avec la date et l'heure de capture lorsqu'un fichier valide existe."
  },
