  "Màxima i mínima diàries dels models de base, no predicció pròpia de Fonta. AROME France ja forma part de l’aprenentatge; AROME HD es conserva en paral·lel com a candidat i no modifica la previsió experimental fins que acumuli prou contrast prospectiu. Les diferències entre models no són un interval de confiança. Font: Open-Meteo, ECMWF, DWD i Météo-France.": {
    "es": "Máximas y mínimas diarias de los modelos base, no es una predicción propia de Fonta. AROME Francia ya forma parte del aprendizaje; AROME HD se conserva en paralelo como candidato y no modifica la previsión experimental hasta que acumule suficiente contraste prospectivo. Las diferencias entre modelos no son un intervalo de confianza. Fuente: Open-Meteo, ECMWF, DWD y Météo-France.",
    "en": "Daily maximums and minimums from base models, not a Fonta-specific forecast. AROME France is already part of the learning process; AROME HD remains in parallel as a candidate and does not modify the experimental forecast until it accumulates sufficient prospective contrast. Differences between models are not a confidence interval. Source: Open-Meteo, ECMWF, DWD, and Météo-France.",
    "fr": "Maximums et minimums quotidiens des modèles de base, pas une prédiction propre à Fonta. AROME France fait déjà partie de l'apprentissage ; AROME HD est conservé en parallèle comme candidat et ne modifie pas la prévision expérimentale tant qu'il n'a pas accumulé assez de contraste prospectif. Les différences entre les modèles ne sont pas un intervalle de confiance. Source : Open-Meteo, ECMWF, DWD et Météo-France."
  },
