  "Primer: dades fiables i verificació de la temperatura a Fontanillas. Després: identificació de sortides dels models i comparació amb estacions independents. La pluja, el vent i l’abast regional necessiten protocols propis.": {
    "es": "Primer: datos fiables y verificación de la temperatura a Fontanillas. Después: identificación de salidas de los modelos y comparación con estaciones independientes. La lluvia, el viento y el alcance regional necesitan protocolos propios.",
    "en": "First: reliable data and temperature verification at Fontanillas. Then: identification of model outputs and comparison with independent stations. Rain, wind and regional reach require their own protocols.",
    "fr": "D'abord : données fiables et vérification de la température à Fontanillas. Ensuite : identification des sorties de modèles et comparaison avec des stations indépendantes. La pluie, le vent et l'étendue régionale nécessitent leurs propres protocoles."
  },
