  "Si s’activa el servei i acceptes les notificacions, OneSignal gestiona la subscripció del navegador. El portal conserva un identificador tècnic de subscripció i les categories escollides només per enviar els avisos que has demanat; no identifica la persona ni s’utilitza per a cap altra finalitat. No s’activa sense una acció expressa de l’usuari.": {
    "es": "Si activas el servicio y aceptas las notificaciones, OneSignal gestiona la suscripción del navegador. El portal conserva un identificador técnico de suscripción y las categorías elegidas únicamente para enviar los avisos que has solicitado; no identifica a la persona ni se utiliza para ninguna otra finalidad. El servicio no se activa sin una acción expresa del usuario.",
    "en": "If you activate the service and accept notifications, OneSignal manages the browser subscription. The portal keeps a technical subscription ID and the selected categories only to send the alerts you requested; the ID does not identify a person and is not used for any other purpose. The service is not activated without an explicit user action.",
    "fr": "Si vous activez le service et acceptez les notifications, OneSignal gère l’abonnement du navigateur. Le portail conserve un identifiant technique d’abonnement et les catégories choisies uniquement pour envoyer les alertes demandées ; cela ne permet pas d’identifier la personne et n’est utilisé à aucune autre fin. Le service ne s’active pas sans action expresse de l’utilisateur."
  },
