  "Taula de backtest: errors recalculats cronològicament, només amb el passat disponible a cada pas. MAE: error absolut mitjà en °C; més baix és millor. Es comparen quatre fonts, la mitjana de tres models, persistència i la correcció Fonta. La persistència repeteix l’últim dia complet anterior a l’emissió. No és una prova independent de superioritat.": {
    "es": "Tabla de backtest: errores recalculados cronológicamente, solo con el pasado disponible a cada paso. MAE: error absoluto medio en °C; más bajo es mejor. Se comparan cuatro fuentes, la media de tres modelos, persistencia y la corrección Fonta. La persistencia repite el último día completo anterior a la emisión. No es una prueba independiente de superioridad.",
    "en": "Backtest table: errors recalculated chronologically, only with past available at each step. MAE: mean absolute error in °C; lower is better. Four sources are compared, the average of three models, persistence, and Fonta correction. Persistence repeats the last full day prior to emission. It is not an independent test of superiority.",
    "fr": "Tableau de backtest : erreurs recalculées chronologiquement, uniquement avec le passé disponible à chaque étape. MAE : erreur absolue moyenne en °C ; plus bas est mieux. Quatre sources sont comparées, la moyenne de trois modèles, la persistance et la correction Fonta. La persistance répète le dernier jour complet antérieur à l'émission. Ce n'est pas un test indépendant de supériorité."
  },
