  "Temperatura global observada respecte de 1850–1900, amb incertesa de ±0,13 °C. És la mitjana de diversos conjunts de dades de l'indicador IGCC; la sèrie ERA5 de Copernicus C3S dona +1,47 °C per al mateix any amb un altre mètode.": {
    "es": "Temperatura global observada respecto de 1850–1900, con una incertidumbre de ±0,13 °C. Es la media de varios conjuntos de datos del indicador IGCC; la serie ERA5 de Copernicus C3S da +1,47 °C para el mismo año con otro método.",
    "en": "Observed global temperature relative to 1850–1900, with an uncertainty of ±0.13 °C. It is the average of several IGCC indicator datasets; the Copernicus C3S ERA5 series gives +1.47 °C for the same year with another method.",
    "fr": "Température globale observée par rapport à 1850–1900, avec une incertitude de ±0,13 °C. Il s'agit de la moyenne de plusieurs ensembles de données de l'indicateur IGCC ; la série ERA5 de Copernicus C3S donne +1,47 °C pour la même année avec une autre méthode."
  },
