  "Temperatura superficial en °C, amb dades d'anàlisi i previsió properes al temps real. La data i el producte utilitzat es consulten al mateix visor; no és una mesura instantània de cada platja. Les boies de Portus són observacions puntuals i es consulten per separat.": {
    "es": "Temperatura superficial en °C, con datos de análisis y predicción cercanos al tiempo real. La fecha y el producto utilizado se consultan en el mismo visor; no es una medida instantánea de cada playa. Las boyas de Portus son observaciones puntuales y se consultan por separado.",
    "en": "Surface temperature in °C, with analysis and near-real-time forecast data. The date and product used are consulted on the same viewer; it is not an instantaneous measurement of each beach. Portus buoys are point observations and are consulted separately.",
    "fr": "Température de surface en °C, avec des données d'analyse et de prévision proches du temps réel. La date et le produit utilisés sont consultés sur le même affichage ; il ne s'agit pas d'une mesure instantanée de chaque plage. Les bouées de Portus sont des observations ponctuelles et sont consultées séparément."
  },
