  "Tria la teva xarxa preferida per seguir les dades, la predicció, els avisos i els vídeos de Meteo Fontanillas. Tots els perfils d’aquesta pàgina són oficials.": {
    "es": "Selecciona tu red preferida para seguir los datos, la predicción, las alertas y los vídeos de Meteo Fontanillas. Todos los perfiles de esta página son oficiales.",
    "en": "Choose your preferred network to follow the data, forecast, alerts and videos from Meteo Fontanillas. All profiles on this page are official.",
    "fr": "Choisissez votre réseau préféré pour suivre les données, la prévision, les alertes et les vidéos de Meteo Fontanillas. Tous les profils de cette page sont officiels."
  },
  "Tria lloc i hora, mou-te en qualsevol direcció i identifica estrelles, constel·lacions, planetes, el Sol i la Lluna.": {
    "es": "Selecciona lugar y hora, muévete en cualquier dirección e identifica estrellas, constelaciones, planetas, el Sol y la Luna.",
    "en": "Choose a location and time, move in any direction and identify stars, constellations, planets, the Sun and the Moon.",
    "fr": "Choisissez un lieu et une heure, déplacez-vous dans n'importe quelle direction et identifiez les étoiles, les constellations, les planètes, le Soleil et la Lune."
  },
  "Tria un model per veure com evolucionen la pluja, els núvols, el vent o la temperatura sobre Sant Celoni. Aquesta consulta visual no modifica la previsió ni els pesos locals de l’Observatori.": {
    "es": "Selecciona un modelo para ver cómo evolucionan la lluvia, las nubes, el viento o la temperatura sobre Sant Celoni. Esta consulta visual no modifica la previsión ni los pesos locales del Observatorio.",
    "en": "Choose a model to see how rain, clouds, wind or temperature evolve over Sant Celoni. This visual query does not modify the forecast or local weights of the Observatory.",
    "fr": "Choisissez un modèle pour voir comment la pluie, les nuages, le vent ou la température évoluent sur Sant Celoni. Cette requête visuelle ne modifie pas la prévision ni les poids locaux de l'Observatoire."
  },
  "Tria una vegada quins fenòmens t’interessen. Les notificacions del navegador s’activaran quan el servei push estigui configurat.": {
    "es": "Selecciona una vez qué fenómenos te interesan. Las notificaciones del navegador se activarán cuando el servicio push esté configurado.",
    "en": "Choose once which phenomena you are interested in. Browser notifications will be activated when the push service is configured.",
    "fr": "Choisissez une fois quels phénomènes vous intéressent. Les notifications du navigateur seront activées lorsque le service push sera configuré."
  },
