  "Windy": {
    "es": "Viento fuerte",
    "en": "Windy",
    "fr": "Vent fort"
  },
  "Windy és l’explorador visual i conserva la seva atribució i accés originals. HARMONIE-AROME es consulta al visor oficial d’AEMET (2,5 km, fins a 48 h); NEMS, ALADIN i les variants d’AROME serveixen per contrastar escenaris, però no entren automàticament en el càlcul ni en els pesos locals. La vista directa de Catalunya utilitza el WMS oficial d’AROME de Météo-France i el detall del Baix Montseny conserva AROME France HD via Open-Meteo.": {
    "es": "El viento fuerte es el explorador visual que conserva su atribución y acceso originales. HARMONIE-AROME se consulta en el visor oficial de AEMET (2,5 km, hasta 48 h); NEMS, ALADIN y las variantes de AROME sirven para contrastar escenarios, pero no entran automáticamente en el cálculo ni en los pesos locales. La vista directa de Cataluña utiliza el WMS oficial de AROME de Météo-France y el detalle del Bajo Montseny conserva AROME France HD vía Open-Meteo.",
    "en": "Windy is the visual explorer that preserves its original attribution and access. HARMONIE-AROME is consulted via the official AEMET viewer (2.5 km, up to 48 h); NEMS, ALADIN and AROME variants serve to contrast scenarios but do not automatically enter into the calculation or local weights. The direct view of Catalonia uses the official AROME WMS from Météo-France and the Baix Montseny detail preserves AROME France HD via Open-Meteo.",
    "fr": "Windy est l'explorateur visuel qui conserve son attribution et son accès originaux. HARMONIE-AROME est consulté sur le lecteur officiel d'AEMET (2,5 km, jusqu'à 48 h) ; NEMS, ALADIN et les variantes d'AROME servent à comparer des scénarios mais n'entrent pas automatiquement dans le calcul ni dans les poids locaux. La vue directe de Catalogne utilise le WMS officiel d'AROME de Météo-France et le détail du Baix Montseny conserve AROME France HD via Open-Meteo."
  },
