  "Tria un tema i una variable. Els mapes disponibles aquí només es carreguen quan els obres; les altres fonts s’obren al seu visor complet.": {"es": "Elige un tema y una variable. Los mapas disponibles aquí solo se cargan cuando los abres; las demás fuentes se abren en su visor completo.", "en": "Choose a topic and a variable. Maps here load only when you open them; other sources open in their full viewer.", "fr": "Choisissez un thème et une variable. Les cartes ici ne se chargent que lorsque vous les ouvrez ; les autres sources s’ouvrent dans leur visionneuse complète."},
