  "Mesura, model, previsió i mapa de risc són dades diferents. Comprova sempre la font, l’escala i la data al visor original.": {"es": "Medición, modelo, previsión y mapa de riesgo son datos diferentes. Comprueba siempre la fuente, la escala y la fecha en el visor original.", "en": "Measurements, models, forecasts and risk maps are different data. Always check the source, scale and date in the original viewer.", "fr": "Mesure, modèle, prévision et carte des risques sont des données différentes. Vérifiez toujours la source, l’échelle et la date dans la visionneuse d’origine."},
