  "Mapa de l’índex de precipitació": {"es": "Mapa del índice de precipitación", "en": "Precipitation index map", "fr": "Carte de l’indice de précipitation"},
  "Setembre de 2026 · cartografia mensual. Tria el període per comparar el dèficit o l’excés de pluja.": {"es": "Septiembre de 2026 · cartografía mensual. Elige el período para comparar el déficit o el exceso de lluvia.", "en": "September 2026 · monthly map. Choose a period to compare rainfall deficits or surpluses.", "fr": "Septembre 2026 · carte mensuelle. Choisissez une période pour comparer le déficit ou l’excès de pluie."},
